INSERT OR IGNORE INTO custom_recipes (id, data, created_at) SELECT 'r1', '{"id":"r1","name":"Lemon orzo with salmon","subtitle":"with dill, lemon and spinach","minutes":25,"prepMinutes":10,"servings":4,"macros":{"kcal":520,"protein":38,"carbs":48,"fat":19},"reheat":{"quality":"poor","how":"Salmon dries out and the orzo goes claggy. Cook it for one night."},"ingredients":[{"item":"Salmon fillets","qty":4,"unit":null,"aisle":"Protein"},{"item":"Orzo","qty":300,"unit":"g","aisle":"Pantry"},{"item":"Lemons","qty":2,"unit":null,"aisle":"Produce","prep":"Zest, then halve"},{"item":"Fresh dill","qty":1,"unit":"bunch","aisle":"Produce","prep":"Chop"},{"item":"Garlic","qty":3,"unit":"cloves","aisle":"Produce","prep":"Peel and slice"},{"item":"Baby spinach","qty":100,"unit":"g","aisle":"Produce"},{"item":"Vegetable broth","qty":500,"unit":"ml","aisle":"Pantry","staple":true},{"item":"Olive oil","qty":2,"unit":"tbsp","aisle":"Pantry","staple":true}],"equipment":["Large lidded pan","Kettle or pot for broth"],"callouts":[{"title":"Lidded pan","text":"The lid steams the salmon on top of the orzo, so it cooks in the same pan."}],"steps":[{"title":"Toast the orzo","actions":["Toast the orzo in oil with the sliced garlic for two minutes."]},{"title":"Simmer","actions":["Add broth, simmer 9 minutes, stirring so it doesn''t catch."]},{"title":"Cook the salmon","actions":["Lay the salmon on top, lid on, 8 minutes until it flakes."]},{"title":"Finish","actions":["Off the heat, fold through spinach, dill, and lemon."]}]}', 0 WHERE NOT EXISTS (SELECT 1 FROM hidden_recipes WHERE id = 'r1');
