INSERT OR IGNORE INTO custom_recipes (id, data, created_at) SELECT 'r3', '{"id":"r3","name":"Chicken tikka bites","subtitle":"on rice with charred onion","minutes":40,"prepMinutes":10,"servings":4,"macros":{"kcal":430,"protein":42,"carbs":18,"fat":21},"reheat":{"quality":"great","how":"Keeps three days. Reheat in a hot dry pan for 4 minutes, or eat it cold in a wrap."},"ingredients":[{"item":"Chicken thighs","qty":800,"unit":"g","aisle":"Protein","prep":"Cube"},{"item":"Greek yogurt","qty":150,"unit":"g","aisle":"Dairy"},{"item":"Red onion","qty":1,"unit":null,"aisle":"Produce","prep":"Peel, thin slice"},{"item":"Lemons","qty":1,"unit":null,"aisle":"Produce"},{"item":"Cilantro","qty":1,"unit":"bunch","aisle":"Produce","prep":"Chop"},{"item":"Basmati rice","qty":1,"unit":"cup","aisle":"Pantry"},{"item":"Tikka paste","qty":3,"unit":"tbsp","aisle":"Pantry","staple":true}],"equipment":["Bowl","Grill or air-fryer","Pan for the rice"],"steps":[{"title":"Cook the rice","actions":["Rinse the rice, then into the pan with 1½ cups water and a pinch of salt. Bring to a boil, cover, and simmer low for 12 minutes.","Keep covered off the heat until serving."]},{"title":"Coat the chicken","actions":["Coat the chicken in yogurt and tikka paste."]},{"title":"Marinate","actions":["Leave 20 minutes if you have it, 5 if you don''t."]},{"title":"Grill","actions":["Grill or air-fry 12 minutes, turning once, until charred at the edges."]},{"title":"Serve","actions":["Serve on rice with onion, cilantro, and lemon."]}]}', 0 WHERE NOT EXISTS (SELECT 1 FROM hidden_recipes WHERE id = 'r3');
