INSERT OR IGNORE INTO custom_recipes (id, data, created_at) SELECT 'r4', '{"id":"r4","name":"Black bean chili","subtitle":"with brown rice","minutes":45,"prepMinutes":15,"servings":6,"macros":{"kcal":390,"protein":18,"carbs":58,"fat":9},"reheat":{"quality":"great","how":"Better on day two once the spices settle. Reheat in a pan, splash of water, 8 minutes."},"ingredients":[{"item":"Black beans, canned","qty":30,"unit":"oz","aisle":"Pantry"},{"item":"Diced tomatoes, canned","qty":29,"unit":"oz","aisle":"Pantry"},{"item":"Red bell pepper","qty":2,"unit":null,"aisle":"Produce","prep":"Deseed and dice"},{"item":"Red onion","qty":2,"unit":null,"aisle":"Produce","prep":"Peel and dice"},{"item":"Garlic","qty":4,"unit":"cloves","aisle":"Produce","prep":"Peel and crush"},{"item":"Brown rice","qty":1.5,"unit":"cup","aisle":"Pantry"},{"item":"Ground cumin","qty":2,"unit":"tsp","aisle":"Pantry","staple":true},{"item":"Smoked paprika","qty":2,"unit":"tsp","aisle":"Pantry","staple":true},{"item":"Vegetable oil","qty":1,"unit":"tbsp","aisle":"Pantry","staple":true}],"equipment":["Large heavy pot","Medium pot for the rice"],"callouts":[{"title":"Make it a day ahead","text":"The spices settle overnight. This is the one to cook double."}],"steps":[{"title":"Cook the rice","actions":["Rice, 3 cups water, and a pinch of salt into the medium pot. Bring to a boil, cover, and simmer low for 40 minutes until tender.","Keep covered off the heat until serving."]},{"title":"Soften the vegetables","actions":["Heat the oil in the large pot over medium. Soften the onion, pepper, and garlic for 8 minutes."]},{"title":"Add spices, tomatoes and beans","actions":["Add the spices, cook a minute, then tomatoes and drained beans."]},{"title":"Simmer","actions":["Simmer 25 minutes until it thickens."]},{"title":"Serve","actions":["Fluff the rice and spoon the chili over it."]}]}', 0 WHERE NOT EXISTS (SELECT 1 FROM hidden_recipes WHERE id = 'r4');
