INSERT OR IGNORE INTO custom_recipes (id, data, created_at) SELECT 'r11', '{"id":"r11","name":"Miso cod with greens","subtitle":"with miso glaze and jasmine rice","minutes":25,"prepMinutes":10,"servings":2,"macros":{"kcal":400,"protein":38,"carbs":22,"fat":16},"reheat":{"quality":"poor","how":"White fish doesn''t survive a second heating. Eat it the night you cook it."},"ingredients":[{"item":"Cod fillets","qty":2,"unit":null,"aisle":"Protein"},{"item":"Bok choy","qty":2,"unit":null,"aisle":"Produce","prep":"Halve lengthwise"},{"item":"Ginger","qty":15,"unit":"g","aisle":"Produce","prep":"Peel and grate"},{"item":"Jasmine rice","qty":0.75,"unit":"cup","aisle":"Pantry"},{"item":"White miso","qty":2,"unit":"tbsp","aisle":"Pantry","staple":true},{"item":"Honey","qty":1,"unit":"tbsp","aisle":"Pantry","staple":true},{"item":"Sesame oil","qty":1,"unit":"tbsp","aisle":"Pantry","staple":true}],"equipment":["Small bowl","Grill and grill tray","Steamer or lidded pan","Pot for the rice"],"steps":[{"title":"Cook the rice","actions":["Rinse the rice, then into the pot with 1¼ cups water and a pinch of salt. Bring to a boil, cover, and simmer low for 15 minutes.","Keep covered off the heat until serving."]},{"title":"Make the glaze","actions":["Mix miso, honey, ginger, and sesame oil into a glaze."]},{"title":"Grill the cod","actions":["Brush over the cod, grill 8 minutes until it lacquers."]},{"title":"Steam and serve","actions":["Steam the bok choy 3 minutes.","Serve on rice with the pan juices."]}]}', 0 WHERE NOT EXISTS (SELECT 1 FROM hidden_recipes WHERE id = 'r11');
