INSERT OR IGNORE INTO custom_recipes (id, data, created_at) SELECT 'r12', '{"id":"r12","name":"Sausage and white bean stew","subtitle":"with kale","minutes":35,"prepMinutes":10,"servings":4,"macros":{"kcal":520,"protein":28,"carbs":42,"fat":26},"reheat":{"quality":"great","how":"Deepens overnight. Reheat gently for 10 minutes; add the second night''s greens fresh."},"ingredients":[{"item":"Pork sausages","qty":8,"unit":null,"aisle":"Protein"},{"item":"Cannellini beans, canned","qty":30,"unit":"oz","aisle":"Pantry"},{"item":"Diced tomatoes, canned","qty":14.5,"unit":"oz","aisle":"Pantry"},{"item":"Onion","qty":1,"unit":null,"aisle":"Produce","prep":"Peel and dice"},{"item":"Garlic","qty":3,"unit":"cloves","aisle":"Produce","prep":"Peel and crush"},{"item":"Kale","qty":200,"unit":"g","aisle":"Produce","prep":"Strip and shred"},{"item":"Smoked paprika","qty":2,"unit":"tsp","aisle":"Pantry","staple":true},{"item":"Olive oil","qty":1,"unit":"tbsp","aisle":"Pantry","staple":true}],"equipment":["Large lidded pot or casserole"],"steps":[{"title":"Brown the sausages","actions":["Brown the sausages whole, then set aside and slice thickly."]},{"title":"Build the base","actions":["Soften onion and garlic in the fat, add paprika and tomatoes."]},{"title":"Simmer","actions":["Beans and sausages back in, simmer 15 minutes."]},{"title":"Add the kale","actions":["Stir the kale through for the last 4 minutes."]}]}', 0 WHERE NOT EXISTS (SELECT 1 FROM hidden_recipes WHERE id = 'r12');
