INSERT OR IGNORE INTO custom_recipes (id, data, created_at) SELECT 'r13', '{"id":"r13","name":"Mushroom and chive risotto","subtitle":"with grape tomatoes, Parmesan and garlic herb butter","minutes":60,"prepMinutes":10,"servings":2,"macros":{"kcal":590,"protein":16,"carbs":84,"fat":21},"reheat":{"quality":"ok","how":"Firms up overnight. Reheat in a pan with a splash of stock over low heat for 5 minutes, stirring, and finish with fresh chives."},"ingredients":[{"item":"Button mushrooms","qty":115,"unit":"g","aisle":"Produce","prep":"Trim, thin slice"},{"item":"Yellow onion","qty":0.5,"unit":null,"aisle":"Produce","prep":"Halve, peel, dice"},{"item":"Garlic","qty":1,"unit":"cloves","aisle":"Produce","prep":"Peel and mince or grate"},{"item":"Grape tomatoes","qty":115,"unit":"g","aisle":"Produce","prep":"Halve"},{"item":"Chives","qty":0.25,"unit":"oz","aisle":"Produce","prep":"Mince"},{"item":"Arborio rice","qty":0.75,"unit":"cup","aisle":"Pantry"},{"item":"Garlic herb butter","qty":2,"unit":"tbsp","aisle":"Dairy"},{"item":"Parmesan","qty":25,"unit":"g","aisle":"Dairy"},{"item":"Veggie stock concentrate","qty":2,"unit":null,"aisle":"Pantry","staple":true},{"item":"Chilli flakes","qty":1,"unit":"tsp","aisle":"Pantry","staple":true},{"item":"Butter","qty":0.5,"unit":"tbsp","aisle":"Dairy","staple":true},{"item":"Olive oil","qty":2,"unit":"tsp","aisle":"Pantry","staple":true}],"equipment":["Medium pot for the stock","Large pan"],"callouts":[{"title":"Garlic herb butter","text":"Stirred in at the end, it brings garlic and herbs in one go and leaves the risotto glossy."},{"title":"Stay close","text":"Add the stock a little at a time and stir often. Stirring works the starch out of the rice, and that starch is what makes it creamy."}],"steps":[{"title":"Heat the stock","actions":["Bring 4 cups water and both stock concentrates to a boil in a medium pot, then turn it down so it barely simmers.","Rinse and dry the vegetables. Slice the mushrooms thinly, dice the onion and mince the garlic."]},{"title":"Brown the mushrooms","actions":["Warm a drizzle of oil in a large pan over medium-high heat. Add the mushrooms and let them brown and crisp at the edges, stirring occasionally, 5-7 minutes. Season with salt and pepper.","Take the pan off the heat, set the mushrooms aside on a plate and wipe the pan clean."]},{"title":"Toast the rice","actions":["Return the pan to medium heat with another drizzle of oil. Cook the onion until it softens and just starts to color, 2-3 minutes.","Stir in the garlic, rice and butter, and cook until the garlic is fragrant and the rice looks translucent at the edges, 1-2 minutes. Season with salt and pepper."]},{"title":"Add the stock and finish prep","actions":["Pour in ½ cup hot stock and stir until the rice has soaked up most of it. Keep adding stock ½ cup at a time, stirring, until the rice is creamy and tender with a little bite, 25-30 minutes. Season well.","While it cooks, halve the tomatoes and mince the chives."],"tip":"Pans vary, so you may use a little more or less stock."},{"title":"Stir it together","actions":["Fold in the mushrooms, tomatoes, garlic herb butter, half the Parmesan and half the chives. Cook until the tomatoes just soften, 2-3 minutes.","Take it off the heat. Stir in a pinch of chili flakes now if you want heat all through."],"tip":"If it sets too stiff, loosen it with a splash of stock or water."},{"title":"Serve","actions":["Spoon into bowls and finish with the rest of the chives and Parmesan and a pinch of chili flakes."]}]}', 0 WHERE NOT EXISTS (SELECT 1 FROM hidden_recipes WHERE id = 'r13');
